import json, os
D = os.path.dirname(os.path.abspath(__file__))
keys = list(T.keys())
json.dump(keys, open(os.path.join(D, "p5_keys.json"), "w", encoding="utf-8"), ensure_ascii=False, indent=0)
with open(os.path.join(D, "p5_01.tsv"), "w", encoding="utf-8") as f:
    f.write("#Nr\ten\tes\tja\tru\tnl\tel\n")
    for i, k in enumerate(keys):
        v = [x.replace("\t", " ") for x in T[k]]
        assert len(v) == 6, k
        f.write("\t".join([str(i)] + v) + "\n")
print(len(keys), "Einträge")
